import { Component, h, Prop, Host } from '@stencil/core';
import { formatCSSLength } from '@src/shared/dom';

const prefix = 'toast-box';

@Component({
  tag: 'ks-toast-box',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsToastBox {
  /** The z-index of the toast box container. If not provided, a default value from the store will be used. */
  @Prop() zIndex?: number;
  /** Offset from the page block-start (top) for the toast container. When set, it overrides the default gap. */
  @Prop() topOffset?: number;

  render() {
    return (
      <Host class="KsToastBox">
        <div class={`${prefix}__wrap`} style={{ zIndex: `${this.zIndex || 2000}` }}>
          <div class={`${prefix}`} style={{ marginTop: formatCSSLength(this.topOffset) }}>
            <slot></slot>
          </div>
        </div>
      </Host>
    );
  }
}
